void advManager::castSpell(SpellID whichSpell)
{
    hero* who = g_game->getCurrHero();
    if (who == 0)
        return;

    TSkillMastery level
        = who->getSpellLevel(whichSpell, who->getSpecialTerrain());

    switch (whichSpell) {
    case SPELL_SUMMON_BOAT:
        summonBoat(level);
        break;
    case SPELL_SCUTTLE_BOAT:
        skuttleBoat(level);
        break;
    case SPELL_VISIONS:
        identify(level);
        break;
    case SPELL_VIEW_EARTH:
        launchSample(DATA_COMPGEN(0x006604C4, castSpellViewSample,
                                   "view.wav"),
                      -1, 3);
        viewWorld(SPELL_VIEW_EARTH, level);
        who->useSpell(who->getManaCost(SPELL_VIEW_EARTH));
        break;
    case SPELL_DISGUISE:
        disguise(level);
        break;
    case SPELL_VIEW_AIR:
        launchSample(DATA_COMPGEN(0x006604C4, castSpellViewSample,
                                   "view.wav"),
                      -1, 3);
        viewWorld(SPELL_VIEW_AIR, level);
        who->useSpell(who->getManaCost(SPELL_VIEW_AIR));
        break;
    case SPELL_FLY:
        flight(level);
        break;
    case SPELL_WATER_WALK:
        waterWalk(level);
        break;
    case SPELL_DIMENSION_DOOR:
        dimensionDoor(level);
        break;
    case SPELL_TOWN_PORTAL:
        townGate(level);
        break;
    }
}

